 this value" data-marker-detail-action={node.actions.action} data-marker-detail-id={node.actions.id??undefined} data-marker-detail-date={node.actions.date??undefined} data-marker-detail-type={node.actions.type??undefined}>+ note</div>{:else if node.kind === "alternate-value"}<div class="mv-alt" title="Same value, alternate unit">≈ {node.value} {node.unit}</div>{:else if node.kind === "row"}<div class="modal-value-card marker-history-row status-{node.status}">{#if node.deleteButton}{@render history(node.deleteButton)}{/if}
      <div class="marker-history-date-row"><div class="mv-date">{node.date}{#if node.dateNote}{@render history(node.dateNote)}{/if}</div>{#each node.source as source}{@render history(source)}{/each}</div>
      <div class="marker-history-value-row"><!-- svelte-ignore a11y_no_noninteractive_tabindex (The native editable history value gains role button and tabindex together only when its captured edit action exists.) --><div class="mv-value val-{node.valueStatus}" data-marker-detail-action={node.editAttributes?.action} data-marker-detail-id={node.editAttributes?.id??undefined} data-marker-detail-date={node.editAttributes?.date??undefined} data-marker-detail-value={node.editAttributes?.value??undefined} role={node.editAttributes?'button':undefined} tabindex={node.editAttributes?0:undefined} title={node.editAttributes?'Click to edit':undefined} style={node.editAttributes?componentStaticStyles.pointer:undefined}>{node.value}{#if node.manualBadge}{@render history(node.manualBadge)}{/if}</div><div class="mv-status val-{node.badgeStatus}">{node.statusLabel}</div></div>
      {#if node.alternate}{@render history(node.alternate)}{/if}{#if node.phase}{@render history(node.phase)}{/if}{#if node.collection}{@render history(node.collection)}{/if}{#if node.valueNote}{@render history(node.valueNote)}{/if}</div>{:else if node.kind === "more"}<button class="marker-history-show-more" data-marker-detail-action={node.actions.action} data-marker-detail-id={node.actions.id??undefined} data-marker-detail-show-all-history={node.actions.showAllHistory??undefined} data-marker-detail-history-limit={node.actions.historyLimit??undefined} data-marker-detail-scroll-to-history={node.actions.scrollToHistory??undefined}>{node.label}</button>{:else if node.kind === "last-values"}<button class="marker-history-show-more" data-marker-detail-action={node.actions.action} data-marker-detail-id={node.actions.id??undefined} data-marker-detail-scroll-to-history={node.actions.scrollToHistory??undefined}>Show last {node.count} values</button>{:else if node.kind === "trend"}<div class="modal-ref-info"><strong>Trend:</strong> {node.direction} by {node.change} {node.unit} ({node.sign}{node.percentage}%) from {node.firstDate} to {node.lastDate}</div>{:else if node.kind === "collection-context"}<div class="mv-collection-context">{node.text}</div>{:else if node.kind === "source-file"}<div class="mv-source" title="{node.title}">{node.text}</div>{:else if node.kind === "source-edited"}<div class="mv-source mv-source-manual">manually edited</div>{:else if node.kind === "source-report"}<div class="mv-source">Imported report{node.manualLabel}</div>{:else if node.kind === "source-manual"}<div class="mv-source mv-source-manual">manual entry</div>{/if}{/snippet}{@render history(view)}